### Example: Minimal working style (web-only)

```json
{
  "version": 8,
  "sources": { "osm": { "type": "raster", "tiles": ["https://a.tile.openstreetmap.org/{z}/{x}/{y}.png"], "tileSize": 256 } },
  "layers": [
    {
      "id": "water",
      "type": "raster",
      "source": "osm"
    },
    {
      "id": "city-labels",
      "type": "symbol",
      "source": "osm",
      "layout": {
        "text-field": ["get", "name"],
        "text-font": ["MyBrand Regular", "sans-serif"],
        "text-size": 14
      },
      "paint": {
        "text-color": "#222"
      }
    }
  ]
}
```

```html
<link rel="stylesheet" href="https://unpkg.com/maplibre-gl@latest/dist/maplibre-gl.css" />
<style>
@font-face {
  font-family: "MyBrand Regular";
  src: url("/fonts/MyBrand-Regular.woff2") format("woff2");
}
</style>
<div id="map" style="width:100%;height:100vh;"></div>
<script src="https://unpkg.com/maplibre-gl@latest/dist/maplibre-gl.js"></script>
<script>
